// CSD_RATIONALE_BEGIN
// ROOT CAUSE ANALYSIS from attempts 56-57:
//   - `RenderedEndsWith` intercepts EVERY organic `<<` span and routes it through
//     AdaptiveConstrainedStep, which hard-masks logits via MaskValidNextAndEos.
//     After CloseConstrainedSpan returns `>>`, the model's continuation (via
//     UnconstrainedStep) enters a degenerate `!!!!` repetition loop consuming
//     500+ tokens of budget — wiping out all accuracy gains.
//   - The `minSpanTokens=5` delay in attempt 57 made things worse by keeping
//     the span open past complete sub-expressions, hitting dead-ends.
//   - Attempts 56-57 also produced tiny spans (avg 3.78 tokens) because
//     CloseSpanIfComplete fires on the first complete sub-expression (e.g., `<<n>>`).
//
// FIX: Replace the incremental step-by-step constrained inner loop with a single
// CloseSpanWithinBudget call per span. This helper:
//   1. Generates forward inside the span using dead-end-aware steps.
//   2. Tracks the LONGEST prefix that parses as complete.
//   3. Emits `>>` at that maximal complete point in ONE call.
//   There is no back-and-forth constrained/unconstrained transition, so the
//   model context after close is clean and avoids the `!!!!` continuation.
//
// Additionally: detect 3 consecutive identical tokens in unconstrained mode
// and break immediately (catches any residual `!!!` loops cheaply).
//
// spanBudget=20 gives enough room for GSM-symbolic expressions (typical 3-10 tokens).
// With 900 total steps and 36 avg free tokens before first span plus ~3.61 spans ×
// 20 steps each ≈ 108 span steps, leaving ~756 steps for free reasoning.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// 1. parser_validity: `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`
//    Outside-span branch: insideConstrainedOut stays false (implication vacuous) until
//    RenderedEndsWith("<<") fires. EnterObservedConstrainedSpan sets currentConstrainedOut := [],
//    and parser.IsValidPrefix([]) holds by the method's precondition. ✓
//    Inside-span branch: CloseSpanWithinBudget postcondition explicitly guarantees
//    `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)` for the returned
//    (ci, cc). Whether the span closes (ci=false, cc=[]) or stays open (ci=true, cc valid
//    prefix), the invariant holds. ✓
//
// 2. progress: `|generated| <= |generatedPrefix| + steps`
//    Outside-span branch: steps grows by exactly 1; generated grows by at most 1 token
//    (EOS path breaks without appending). Repetition break does not grow generated beyond
//    the just-appended token. After RenderedEndsWith, EnterObservedConstrainedSpan is
//    cost-0 and does not change generated. Invariant preserved. ✓
//    Inside-span branch: spanBudget := min(20, maxSteps - steps), so steps + spanBudget
//    <= maxSteps. CloseSpanWithinBudget postcondition gives |cg| <= |generated| + spanBudget.
//    After steps := steps + spanBudget, |generated| = |cg| <= |generatedPrefix| + old_steps
//    + spanBudget = |generatedPrefix| + new_steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step using the exact symbolic variable names from the problem statement. " +
  "For each calculation step and for the final answer, write the arithmetic expression inside " +
  "<< >> delimiters. Use Python operators (+, -, *, /, //, **, %). " +
  "Do NOT use curly braces inside << >> spans. " +
  "The LAST << >> span must contain the complete Python arithmetic expression that evaluates to the final answer.");

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    // Repetition-loop guard: 3 consecutive identical tokens (e.g., "!!!") signals
    // a degenerate generation state; break before it consumes the whole budget.
    if |generated| >= 3
       && generated[|generated| - 1] == generated[|generated| - 2]
       && generated[|generated| - 2] == generated[|generated| - 3] {
      break;
    }
    if RenderedEndsWith(generated, "<<") {
      generated, insideConstrainedOut, currentConstrainedOut :=
        helpers.EnterObservedConstrainedSpan(lm, generated);
    }
  } else {
    // Inside a constrained span: delegate the entire span lifecycle to
    // CloseSpanWithinBudget, which advances to the MAXIMAL complete parse
    // and emits ">>" in a single call — no interleaved constrained/unconstrained
    // transitions that destabilise the model's continuation context.
    var remaining := maxSteps - steps;
    var spanBudget: nat := if remaining >= 20 then 20 else remaining;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + spanBudget;
  }
}

cost := steps;

